using Microsoft.AspNetCore.Authorization;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", [Authorize] async (ApplicationDbContext db) =>
        {
            return await db.Shipments.Select(s => ToDto(s)).ToListAsync();
        });

        group.MapGet("/track/{trackingNumber}", [AllowAnonymous] async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
            return shipment is null ? Results.NotFound() : Results.Ok(ToDto(shipment));
        });

        group.MapGet("/customer/{email}", [Authorize] async (string email, ApplicationDbContext db) =>
        {
            return await db.Shipments
                .Where(s => s.CustomerEmail == email)
                .Select(s => ToDto(s))
                .ToListAsync();
        });

        group.MapPut("/{id}/status", [Authorize] async (int id, ShipmentStatus status, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            shipment.Status = (Models.ShipmentStatus)(int)status;
            await db.SaveChangesAsync();
            return Results.NoContent();
        });
    }

    private static ShipmentDto ToDto(Models.Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (ShipmentStatus)(int)s.Status,
        ShippedDate = s.ShippedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        CustomerEmail = s.CustomerEmail,
        Description = s.Description
    };
}

